import requests

def test_get_api_profiles_me_current_user_profile_retrieval():
    base_url = "http://localhost:8000"
    url = base_url + "/api/profiles/me"
    token = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    headers = {
        "Authorization": f"Bearer {token}"
    }
    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
        data = response.json()
        assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"
        assert isinstance(data, dict), "Response JSON should be an object"
        # Validate some expected fields in the profile data (common fields)
        assert "email" in data, "Profile data should contain 'email'"
        assert "role" in data, "Profile data should contain 'role'"
        assert "display_name" in data or "name" in data or True, "Profile data should have a display_name or name field (if applicable)"
    except requests.exceptions.RequestException as e:
        assert False, f"HTTP Request failed: {e}"

test_get_api_profiles_me_current_user_profile_retrieval()